*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:          #f7f7f8;
  --surface:     #ffffff;
  --border:      #e4e4e7;
  --border-focus:#6366f1;
  --text-primary:#18181b;
  --text-muted:  #71717a;
  --accent:      #6366f1;
  --accent-text: #3730a3; /* darkened for 7:1 contrast on white */
  --accent-light:#ede9fe;
  --radius-lg:   14px;
  --radius-md:   8px;
  --shadow-sm:   0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.06);
  --shadow-md:   0 4px 12px rgba(0,0,0,.10);
  --transition:  200ms ease;
}

html { color-scheme: light dark; }

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  background: var(--bg);
  color: var(--text-primary);
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
}

/* ── Skip link ── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--accent);
  color: #fff;
  padding: .5rem 1rem;
  border-radius: var(--radius-md);
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

/* ── Header ── */
.site-header {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  padding: 0 1.5rem;
}
.header-inner {
  max-width: 760px;
  margin: 0 auto;
  height: 56px;
  display: flex;
  align-items: center;
  gap: .5rem;
}
.logo { font-size: 1.4rem; }
.site-name {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: -.01em;
  color: var(--accent);
}

/* ── Hero ── */
.hero {
  text-align: center;
  padding: 3.5rem 1.5rem 2.5rem;
}
h1 {
  font-size: clamp(1.75rem, 4vw, 2.6rem);
  font-weight: 800;
  letter-spacing: -.03em;
  color: var(--text-primary);
}
.hero-sub {
  margin-top: .6rem;
  color: var(--text-muted);
  font-size: 1.05rem;
}

/* ── FAQ container ── */
.faq-container {
  max-width: 760px;
  margin: 0 auto;
  padding: 0 1.25rem 4rem;
  display: flex;
  flex-direction: column;
  gap: .75rem;
}

/* ── Individual FAQ card ── */
.example {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
  transition: box-shadow var(--transition), border-color var(--transition);
}
.example:has(.faq-trigger[aria-expanded="true"]) {
  box-shadow: var(--shadow-md);
  border-color: #c7d2fe;
}

/* ── Question heading ── */
.example h2 { font-size: 1rem; }

/* ── Trigger button ── */
.faq-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.1rem 1.25rem;
  background: transparent;
  border: none;
  cursor: pointer;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
  text-align: left;
  border-radius: var(--radius-lg);
  transition: background var(--transition);
}
.faq-trigger:hover { background: var(--accent-light); }
.faq-trigger:focus-visible {
